'use client';
import { useState } from 'react';
import { Edit3, ImagePlus, Plus, Search, X } from 'lucide-react';
const initialPosts = [{ title: 'Reading liquidity before the move', category: 'Market Structure', status: 'Published', date: 'May 18, 2026' }, { title: 'The risk-first framework for consistent traders', category: 'Risk', status: 'Published', date: 'May 10, 2026' }, { title: 'What makes an AI signal worth acting on?', category: 'Product', status: 'Draft', date: 'Apr 29, 2026' }, { title: 'Build a process your emotions cannot break', category: 'Psychology', status: 'Published', date: 'Apr 14, 2026' }];
export default function BlogManager() { const [posts, setPosts] = useState(initialPosts); const [open, setOpen] = useState(false); const [title, setTitle] = useState(''); const [body, setBody] = useState(''); const save = () => { if (!title) return; setPosts([{ title, category: 'Market Structure', status: 'Draft', date: 'Just now' }, ...posts]); setTitle(''); setBody(''); setOpen(false); }; return <div className="p-5 md:p-8 lg:p-10"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.25em] text-cyan">Content studio</p><h1 className="mt-3 text-3xl font-black">Blog Posts</h1></div><button onClick={() => setOpen(true)} className="flex items-center gap-2 rounded-xl bg-cyan px-4 py-3 text-sm font-bold text-ink"><Plus className="h-4 w-4" /> New Post</button></div><div className="mt-8 flex items-center gap-3 rounded-xl border border-white/10 bg-card px-4 py-3 text-sm text-muted"><Search className="h-4 w-4" /> Search posts...</div><div className="mt-4 overflow-x-auto rounded-2xl border border-white/10 bg-card"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-b border-white/10 text-xs uppercase tracking-widest text-muted"><tr><th className="p-5">Title</th><th>Category</th><th>Status</th><th>Published</th><th /></tr></thead><tbody>{posts.map((post) => <tr className="border-b border-white/10 last:border-0" key={post.title}><td className="p-5 font-semibold">{post.title}</td><td className="text-muted">{post.category}</td><td><span className={`rounded-full px-2 py-1 text-[10px] font-bold ${post.status === 'Published' ? 'bg-green-400/10 text-green-400' : 'bg-gold/10 text-yellow-300'}`}>{post.status}</span></td><td className="text-muted">{post.date}</td><td><Edit3 className="h-4 w-4 text-muted" /></td></tr>)}</tbody></table></div>{open && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-5"><div className="w-full max-w-2xl rounded-2xl border border-white/10 bg-card p-6"><div className="flex justify-between"><h2 className="text-xl font-bold">New Blog Post</h2><button onClick={() => setOpen(false)}><X /></button></div><input value={title} onChange={(e) => setTitle(e.target.value)} className="mt-6 w-full rounded-xl border border-white/10 bg-ink p-3 outline-none focus:border-cyan" placeholder="Post title" /><div className="mt-4 flex gap-3"><select className="rounded-xl border border-white/10 bg-ink p-3 text-sm"><option>Market Structure</option><option>Risk</option><option>Product</option></select><button className="flex items-center gap-2 rounded-xl border border-white/10 px-3 text-sm text-muted"><ImagePlus className="h-4 w-4" /> Thumbnail</button></div><textarea value={body} onChange={(e) => setBody(e.target.value)} className="mt-4 min-h-48 w-full rounded-xl border border-white/10 bg-ink p-3 outline-none focus:border-cyan" placeholder="Write in Markdown..." /><input className="mt-4 w-full rounded-xl border border-white/10 bg-ink p-3 text-sm outline-none focus:border-cyan" placeholder="SEO description" /><button onClick={save} className="mt-5 w-full rounded-xl bg-cyan py-3 font-bold text-ink">Save draft</button></div></div>}</div>; }